```python
def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number (F(0) = 0, F(1) = 1) using memoization."""
    if n < 0:
        raise ValueError("n must be non-negative")

    memo = {}

    def fib(k: int) -> int:
        if k in memo:
            return memo[k]
        if k < 2:
            memo[k] = k
            return k
        memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]

    return fib(n)
```

